# Evaluación de Acto Jurídico, tanda 3: Detección de error del tema 20 (Nulidad), IV.B.1 a IV.B.3.5.
# Regla de cantidad del 2026-10-10: cuatro preguntas por tipo en los subtemas de 10 o más exámenes
# y dos en el resto (una en los subtemas sin exámenes). Esta es la primera de dos tandas: dos
# preguntas en cada subtema importante y una en los demás (17); la tanda siguiente completa el tema.
# La sección de Nulidad no tiene recuadros de Advertencia: los errores salen de las confusiones
# que el propio manual aclara (gravedad de las especies, causales, titulares, plazos, art. 1685).
#
# Formato de cada ítem: el mismo de lote_aplic1.py. El caso es el párrafo de un alumno con uno o
# dos errores; los elementos suelen ser: identificar el error, explicar por qué y dar la regla.
TABLA = 'Detección de error'
PREFIJO = 'aj-det'

